import 'package:material_ui/material_ui.dart';

/// Asset path of the Bloxie logo (generated by `tool/generate_branding.py`).
const brandLogoAsset = 'assets/branding/logo.png';

/// The Bloxie logo. Decorative: the adjacent title text already names the app,
/// so it is excluded from semantics.
class BrandLogo extends StatelessWidget {
  const BrandLogo({required this.size, super.key});

  final double size;

  @override
  Widget build(BuildContext context) {
    return Image.asset(
      brandLogoAsset,
      width: size,
      height: size,
      excludeFromSemantics: true,
    );
  }
}
